{"path": "zipper.py", "content": "class Zipper:
    def __init__(self, tree, path=()):
        self.tree = tree
        self.path = path  # tuple of (direction, parent_value, sibling_subtree)

    @staticmethod
    def from_tree(tree):
        return Zipper(tree)

    def value(self):
        return self.tree["value"]

    def set_value(self, value):
        return Zipper({**self.tree, "value": value}, self.path)

    def left(self):
        child = self.tree["left"]
        if child is None:
            return None
        return Zipper(child, self.path + (("left", self.tree["value"], self.tree["right"]),))

    def set_left(self, tree):
        return Zipper({**self.tree, "left": tree}, self.path)

    def right(self):
        child = self.tree["right"]
        if child is None:
            return None
        return Zipper(child, self.path + (("right", self.tree["value"], self.tree["left"]),))

    def set_right(self, tree):
        return Zipper({**self.tree, "right": tree}, self.path)

    def up(self):
        if not self.path:
            return None
        direction, value, sibling = self.path[-1]
        if direction == "left":
            parent = {"value": value, "left": self.tree, "right": sibling}
        else:
            parent = {"value": value, "left": sibling, "right": self.tree}
        return Zipper(parent, self.path[:-1])

    def to_tree(self):
        z = self
        while z.path:
            z = z.up()
        return z.tree
